import idle.core.*;
import idle.core.upgrades.*;
import idle.core.darkmatter.*;
import idle.core.bigbang.*;
import idle.core.molecules.*;
import idle.core.sky.*;
import java.util.*;
public class RobotPhase18 {
 static void particle(Game g){for(int i=0;i<1200;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.PARTICLES))if(g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void atom(Game g){for(int i=0;i<150;i++){Upgrade b=null;for(Upgrade u:g.upgrades(Resource.ATOMS))if(!u.id().equals("atom_keep")&&g.canBuy(u.id())&&(b==null||g.costOf(u.id()).lt(g.costOf(b.id()))))b=u;if(b==null)break;g.buy(b.id());}}
 static void dark(Game g){for(int i=0;i<100;i++){boolean bought=false;for(DarkUpgrade u:g.darkUpgrades())if(g.canBuyDark(u.id())){g.buyDark(u.id());bought=true;break;}if(!bought)break;}}
 static void post(Game g,int hours){long start=System.nanoTime();int lastKinds=-1,lastSub=-1,lastAssembly=-1,lastBodies=-1,lastMature=-1,lastCosmos=-1;for(int t=1;t<=hours*360;t++){g.tick(10);particle(g);for(int i=0;i<10&&g.canFuse();i++){g.fuse();atom(g);particle(g);}for(Automation a:g.automations()){if(g.canBuyAutomation(a.id()))g.buyAutomation(a.id());if(g.canSpeedUpAutomation(a.id()))g.speedUpAutomation(a.id());}atom(g);for(int i=0;i<20&&g.canSynthesize();i++)g.synthesize();dark(g);for(SpaceUpgrade u:g.spaceUpgrades())if(g.canBuySpaceUpgrade(u.id()))g.buySpaceUpgrade(u.id());g.setAllMoleculesAutomated(true);int created=0;for(Molecule m:g.molecules()){for(int k=0;k<2&&g.canCreateMolecule(m.id());k++){g.createMolecule(m.id());created++;}}for(Molecule m:g.molecules())if(g.canFormSubstance(m.id()))g.formSubstance(m.id());for(Assembly a:g.assemblies())if(g.canFormAssembly(a.id()))g.formAssembly(a.id());for(Body b:g.bodies())if(g.canFormBody(b.id()))g.formBody(b.id());for(Cosmos c:Cosmos.values())if(g.canFormCosmos(c)){g.formCosmos(c);System.out.printf("COSMOS,%s,%.3f%n",c,t/360.0);}if(g.moleculeKindsCreated()!=lastKinds||g.substancesFormed()!=lastSub||g.assembliesFormed()!=lastAssembly||g.bodiesFormed()!=lastBodies||g.bodiesMature()!=lastMature||g.cosmosFormed()!=lastCosmos){if(t%60==0)System.out.printf("PROGRESS,%.3f,kinds=%d,sub=%d,assembly=%d,bodies=%d,mature=%d,cosmos=%d,space=%s%n",t/360.0,g.moleculeKindsCreated(),g.substancesFormed(),g.assembliesFormed(),g.bodiesFormed(),g.bodiesMature(),g.cosmosFormed(),g.state().space());lastKinds=g.moleculeKindsCreated();lastSub=g.substancesFormed();lastAssembly=g.assembliesFormed();lastBodies=g.bodiesFormed();lastMature=g.bodiesMature();lastCosmos=g.cosmosFormed();}if(t%360==0)System.out.printf("POST_HOUR,%d,bangs=%d,expl=%d,elem=%d,molecules=%d,kinds=%d,sub=%d,assembly=%d,bodies=%d,mature=%d,cosmos=%d%n",t/360,g.bigBangs(),g.state().explosions(),g.discoveredElements(),g.moleculesCreated(),g.moleculeKindsCreated(),g.substancesFormed(),g.assembliesFormed(),g.bodiesFormed(),g.bodiesMature(),g.cosmosFormed());if(g.hasCosmos(Cosmos.UNIVERSE)){System.out.printf("UNIVERSE_REACHED,%.3f%n",t/360.0);return;}}System.out.println("POST_END,universe=false,elapsed="+hours+"h");}
 public static void main(String[]args){long seed=args.length>0?Long.parseLong(args[0]):1;int hours=args.length>1?Integer.parseInt(args[1]):12;Game g=new Game(new GameState(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,idle.core.achievements.Achievements.DEFAULT,new Random(seed));g.start();boolean abandoned=false;for(int tick=1;tick<=hours*360;tick++){if(g.completedChallenges()>=10 && g.state().darkMatter().gte(idle.core.math.BigNum.of(500)) && g.achievementCount()>=40 && g.state().explosions()>=4200){if(g.state().atoms().gte(idle.core.math.BigNum.of(1,12)))g.setAutomationEnabled("auto_fusion",false);g.setAutomationEnabled("auto_synthesis",false);}g.tick(10);if(g.completedChallenges()>=10)g.growDarkMatter(10);particle(g);for(int i=0;i<5&&!(g.completedChallenges()>=10 && g.state().darkMatter().gte(idle.core.math.BigNum.of(500)) && g.achievementCount()>=40 && g.state().explosions()>=4200 && g.state().atoms().gte(idle.core.math.BigNum.of(1,12)))&&g.canFuse()&&(tick>180||g.state().stats().fusions()>0);i++){g.fuse();if(g.completedChallenges()<10)atom(g);particle(g);}for(Automation a:g.automations())if(g.canBuyAutomation(a.id()))g.buyAutomation(a.id());for(Automation a:g.automations())if(g.canSpeedUpAutomation(a.id()))g.speedUpAutomation(a.id());if(g.completedChallenges()<10)atom(g);for(int i=0;i<15&&!(g.completedChallenges()>=10 && g.state().darkMatter().gte(idle.core.math.BigNum.of(500)) && g.achievementCount()>=40 && g.state().explosions()>=4200)&&g.canSynthesize();i++)g.synthesize();if(g.state().explosions()<4200)dark(g);if(!g.inChallenge() && g.state().explosions()>=40 && g.darkLevelOf("dark_density")>=3){for(Challenge c:g.challenges())if(g.isChallengeUnlocked(c.id())&&!g.isChallengeCompleted(c.id())){if(g.startChallenge(c.id())){if(!abandoned){g.abandonChallenge();abandoned=true;break;}break;}}}if(g.canExplode() && (g.inChallenge() || (g.completedChallenges()<10 && (g.state().explosions()<40 || g.darkLevelOf("dark_density")>=3)) || (g.completedChallenges()>=10 && (g.state().darkMatter().lt(idle.core.math.BigNum.of(500)) || g.achievementCount()<40 || g.state().explosions()<4200))))g.explode();if(g.canBigBang()){System.out.printf("BIGBANG_READY,%.4f,%d%n",tick/360.0,g.state().explosions());boolean ok=g.bigBang();System.out.println("BIGBANG_EXECUTED,"+ok+",bangs="+g.bigBangs());post(g,20);return;}if(tick%720==0)System.out.printf("PRE_HOUR,%d,expl=%d,challenges=%d,ach=%d%n",tick/360,g.state().explosions(),g.completedChallenges(),g.achievementCount());}System.out.println("NO_BIGBANG");}
}
